-- Independent editorial drafts never replace official names or approve game definitions.
CREATE TABLE editorial_terms(term_id TEXT PRIMARY KEY, parent_id TEXT REFERENCES editorial_terms(term_id), domain TEXT NOT NULL CHECK(domain IN('OBJECT','CULTURE','HISTORY','GEOLOGY','NATURAL')), zh_name TEXT NOT NULL, en_name TEXT NOT NULL, aliases_json TEXT NOT NULL CHECK(json_valid(aliases_json)), authority_url TEXT NOT NULL, review_status TEXT NOT NULL CHECK(review_status IN('DRAFT_PENDING_REVIEW','REVIEWED')));
CREATE TABLE editorial_object_tags(object_id TEXT NOT NULL REFERENCES collection_objects(object_id), term_id TEXT NOT NULL REFERENCES editorial_terms(term_id), source_id TEXT NOT NULL, record_id TEXT NOT NULL, source_path TEXT NOT NULL, source_value_json TEXT NOT NULL CHECK(json_valid(source_value_json)), status TEXT NOT NULL DEFAULT 'DRAFT_PENDING_REVIEW' CHECK(status IN('DRAFT_PENDING_REVIEW','REVIEWED')), PRIMARY KEY(object_id,term_id), FOREIGN KEY(source_id,record_id) REFERENCES source_records(source_id,record_id));
CREATE TABLE editorial_articles(article_id TEXT PRIMARY KEY, object_id TEXT NOT NULL UNIQUE REFERENCES collection_objects(object_id), zh_name TEXT NOT NULL, original_name TEXT NOT NULL, object_type TEXT NOT NULL, civilization_or_geology TEXT, material TEXT, technique_or_preservation TEXT, body TEXT NOT NULL, claims_json TEXT NOT NULL CHECK(json_valid(claims_json)), related_object_ids TEXT NOT NULL CHECK(json_valid(related_object_ids)), confidence TEXT NOT NULL CHECK(confidence IN('SOURCE_BACKED_DRAFT','IDENTIFICATION_PENDING','UNCERTAIN_SOURCE_ATTRIBUTION')), review_status TEXT NOT NULL DEFAULT 'DRAFT_PENDING_REVIEW' CHECK(review_status IN('DRAFT_PENDING_REVIEW','REVIEWED','REJECTED')), ai_generated INTEGER NOT NULL DEFAULT 1 CHECK(ai_generated IN(0,1)), reviewer TEXT, review_note TEXT, content_sha256 TEXT NOT NULL, CHECK(review_status!='REVIEWED' OR (reviewer IS NOT NULL AND length(review_note)>0)));
CREATE TABLE content_review_log(review_id INTEGER PRIMARY KEY, entity_kind TEXT NOT NULL, entity_id TEXT NOT NULL, from_status TEXT NOT NULL, to_status TEXT NOT NULL, reviewer TEXT NOT NULL, note TEXT NOT NULL, content_sha256 TEXT NOT NULL, reviewed_at TEXT NOT NULL);
CREATE INDEX editorial_review ON editorial_articles(review_status,object_type);
